   2. 基于堆实现物理页帧分配管理初始化
   3. 设置satp，启动分页机制，激活内核地址空间KERNELSPACE，
// os/src/mm/mod.rs
pub fn init() {
    heapallocator::initheap();
    frameallocator::initframeallocator();
    KERNELSPACE.exclusiveaccess().activate();
}

